import React from 'react';

export default function Features() {
  const featureList = [
    { icon: "👨‍🏫", title: "Expert Teachers", desc: "Learn from the most experienced teachers in the island." },
    { icon: "📄", title: "Past Paper Discussions", desc: "Detailed discussions on past papers and model papers." },
    { icon: "❄️", title: "AC Lecture Halls", desc: "Comfortable and modern air-conditioned learning environment." },
    { icon: "💻", title: "LMS Access", desc: "Access recorded lessons and study materials anytime, anywhere." }
  ];

  return (
    <div style={{ padding: '60px 20px', backgroundColor: '#ffffff' }}>
      <div style={{ maxWidth: '1100px', margin: '0 auto', display: 'flex', justifyContent: 'center', gap: '20px', flexWrap: 'wrap' }}>
        {featureList.map((f, index) => (
          <div key={index} style={{
            width: '250px', padding: '30px', textAlign: 'center', borderRadius: '15px',
            backgroundColor: '#f8f9fa', boxShadow: '0 4px 10px rgba(0,0,0,0.05)', borderBottom: '4px solid #0056b3'
          }}>
            <div style={{ fontSize: '40px', marginBottom: '15px' }}>{f.icon}</div>
            <h3 style={{ fontSize: '18px', color: '#333', marginBottom: '10px' }}>{f.title}</h3>
            <p style={{ fontSize: '14px', color: '#666', lineHeight: '1.5' }}>{f.desc}</p>
          </div>
        ))}
      </div>
    </div>
  );
}
